patch:
diff --git a/repro/cross-drive-ignore.js b/repro/cross-drive-ignore.js
new file mode 100644
index 0000000..5531b99
--- /dev/null
+++ b/repro/cross-drive-ignore.js
@@ -0,0 +1,68 @@
+"use strict";
+
+/*
+ * Repro for "files on a different drive are not ignored on Windows".
+ * Emulates Windows on Linux: `path`/`node:path` resolve to `path.win32`,
+ * process.platform is "win32", and the cwd is C:\Project (drive C:).
+ * Usage: node repro/cross-drive-ignore.js [path-to-eslint-package]
+ */
+
+const Module = require("node:module");
+const realPath = require("node:path");
+
+const eslintDir = realPath.resolve(process.argv[2] || realPath.join(__dirname, ".."));
+const CWD = "C:\\Project";
+
+const originalLoad = Module._load;
+
+Module._load = function(request, ...rest) {
+    if (request === "path" || request === "node:path") {
+        return realPath.win32;
+    }
+    return originalLoad.call(this, request, ...rest);
+};
+Object.defineProperty(process, "platform", { value: "win32" });
+process.cwd = () => CWD;
+
+const { Linter, ESLint } = require(realPath.join(eslintDir, "lib", "api.js"));
+
+const version = require(realPath.join(eslintDir, "package.json")).version;
+const config = { rules: { "no-undef": "error" } };
+const files = {
+    "inside cwd (control)   C:\\Project\\foo.js": "C:\\Project\\foo.js",
+    "outside cwd, same drive C:\\Other\\foo.js": "C:\\Other\\foo.js",
+    "outside cwd, OTHER drive F:\\foo.js": "F:\\foo.js"
+};
+
+/**
+ * One-line summary of lint messages.
+ * @param {Array} messages messages
+ * @returns {string} summary
+ */
+function summarize(messages) {
+    return messages.length === 0 ? "(no messages)" : messages.map(m => `${m.ruleId || "-"}: ${m.message}`).join(" | ");
+}
+
+(async () => {
+    console.log(`eslint ${version}, emulated win32, cwd=${process.cwd()}\n`);
+
+    console.log("Linter#verify(\"foo()\", { rules: { \"no-undef\": \"error\" } }, filename)");
+    const linter = new Linter({ configType: "flat" });
+
+    for (const [label, file] of Object.entries(files)) {
+        console.log(`  ${label}  ->  ${summarize(linter.verify("foo()", config, file))}`);
+    }
+
+    console.log("\nESLint({ overrideConfigFile: true }) — like `eslint --no-config-lookup`");
+    const eslint = new ESLint({ cwd: CWD, overrideConfigFile: true, overrideConfig: config });
+
+    for (const [label, file] of Object.entries(files)) {
+        const ignored = await eslint.isPathIgnored(file);
+        const [result] = await eslint.lintText("foo();\n", { filePath: file, warnIgnored: true });
+
+        console.log(`  ${label}  ->  isPathIgnored=${ignored}; lintText: ${summarize(result.messages)}`);
+    }
+})().catch(err => {
+    console.error(err);
+    process.exitCode = 2;
+});
